import { HttpErrorResponse, HttpInterceptorFn, HttpResponse } from '@angular/common/http';
import { inject } from '@angular/core';
import { Observable, delay, from, map, of, throwError } from 'rxjs';
import { AuthService } from '../core/auth.service';
import { DemoBackend, DemoError } from './demo-backend';

/** One fake backend per page load: a refresh starts again from the demo data */
const backend = new DemoBackend();

/** Real PDFs generated by the Spring Boot backend, shown as examples in the demo */
const SAMPLE_PDF = { quotes: 'demo/exemple-devis-alef33.pdf', invoices: 'demo/exemple-facture-alef33.pdf' };

/**
 * In demo mode, every call to /api is answered here, in the browser,
 * instead of going to a server.
 */
export const demoInterceptor: HttpInterceptorFn = (req, next) => {
  if (!req.url.includes('/api/')) return next(req);

  // Sample PDFs
  const pdf = req.url.match(/\/api\/(quotes|invoices)\/\d+\/pdf$/);
  if (pdf) {
    const file = SAMPLE_PDF[pdf[1] as 'quotes' | 'invoices'];
    return from(fetch(new URL(file, document.baseURI)).then(r => r.blob())).pipe(
      map(blob => new HttpResponse({ status: 200, body: blob })),
    ) as Observable<any>;
  }

  backend.setRole(inject(AuthService).user()?.role ?? null);
  const url = new URL(req.urlWithParams, location.origin);
  try {
    const body = backend.handle(req.method, url.pathname, url.searchParams, req.body);
    return of(new HttpResponse({ status: req.method === 'POST' ? 201 : 200, body })).pipe(delay(150));
  } catch (e) {
    const err = e instanceof DemoError ? e : new DemoError(500, 'Erreur inattendue dans la démo');
    return throwError(() => new HttpErrorResponse({
      status: err.status,
      url: req.url,
      error: { status: err.status, detail: err.message, errors: err.errors },
    })).pipe(delay(150));
  }
};
